// Glass 3D icon registry: feature name -> file in public/icons/glass/.
// Files are generated by scripts/build-glass-icons.mjs, which reads the
// slugs below, so adding an entry here and re-running the script is all a
// new icon needs. Keep the values as plain 'NNN-slug' string literals.
export const GLASS_ICONS = {
    overview: '004-dashboard',
    finance: '051-wallet',
    schedule: '071-calendar',
    more: '008-menu',
    habit: '079-trophy',
    journal: '061-book',
    gpa: '062-graduation',
    goals: '074-target',
    sticky: '022-document',
    music: '034-music',
    focus: '035-headphones',
    settings: '003-settings',
    admin: '091-shield',
    ai: '086-ai-assistant',
    cv: '067-certificate',
    cashflow: '056-transfer',
    growth: '059-growth',
    savings: '055-savings',
    storage: '092-lock',
    timer: '078-timer',
    tasks: '073-checklist',
    notification: '013-notification',
    pro: '096-verified',
    sync: '087-automation',
    kanban: '077-project',
    chart: '081-bar-chart',
    idea: '068-idea',
    flashcards: '066-flashcards',
    user: '095-user',
    help: '100-help',
    gift: '045-gift',
    email: '012-email',
    chat: '011-chat',
    folder: '021-folder',
    cloud: '025-cloud',
    search: '002-search',
    bank: '053-bank',
    card: '052-bank-card',
    coins: '054-coins',
    lesson: '063-lesson',
    book: '061-book',
    flag: '075-flag',
} as const;

export type GlassIconName = keyof typeof GLASS_ICONS;

/** Icons at or below this CSS size load the 128px file instead of the 512px one. */
export const GLASS_SMALL_MAX = 64;

export const glassIconSrc = (name: GlassIconName, size: number): string =>
    `/icons/glass/${GLASS_ICONS[name]}${size <= GLASS_SMALL_MAX ? '-sm' : ''}.webp`;
